// Parse incoming payload from the previous node
const payload = $input.first().json;
const indices = payload.exchange_index_data || [];
const regime = (payload.market_regime_data || [])[0] || {};

// Escape HTML special characters for Telegram HTML parse mode
const escapeHtml = (str) => String(str ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

// Format numeric values with thousand separators and fixed decimals
const fmtNum = (val, decimals = 2) => {
  if (val === undefined || val === null || isNaN(Number(val))) return 'N/A';
  return Number(val).toLocaleString('en-US', {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals
  });
};

// Order VNINDEX first, followed by VN30
const sortedIndices = [...indices].sort((a, b) => {
  if (a.index_id === 'VNINDEX') return -1;
  if (b.index_id === 'VNINDEX') return 1;
  return 0;
});

// Build formatted blocks for each index
const indexBlocks = sortedIndices.map(idx => {
  const sign = Number(idx.change) >= 0 ? '+' : '';
  const totalValueBillion = Math.round((Number(idx.all_value) || 0) / 1e9).toLocaleString('en-US');

  return [
    `• <b>${escapeHtml(idx.index_id)}:</b> <code>${fmtNum(idx.index_value)}</code> (<b>${sign}${fmtNum(idx.change)}</b> | <b>${sign}${fmtNum(idx.change_percent)}%</b>)`,
    `  └ Range: ${fmtNum(idx.chart_low)} – ${fmtNum(idx.chart_high)} | Total Value: ${totalValueBillion}B VND`,
    `  └ Breadth: 🟢 ${idx.advances} (${idx.ceiling} ceiling) | 🔴 ${idx.declines} (${idx.floor} floor) | 🟡 ${idx.nochanges}`
  ].join('\n');
}).join('\n');

// Safely parse stringified allocation object
let allocText = 'N/A';
try {
  const alloc = typeof regime.allocation === 'string'
    ? JSON.parse(regime.allocation)
    : (regime.allocation || {});
  allocText = `Equity <b>${alloc.w_stock ?? 0}%</b> (VN30: ${alloc['w_vn30/w_stock'] ?? 0}%, MidCap: ${alloc['w_midcap/w_stock'] ?? 0}%) | Cash <b>${alloc.w_cash ?? 0}%</b>`;
} catch (error) {
  allocText = escapeHtml(regime.allocation);
}

const reportDate = regime.time || (sortedIndices[0] && sortedIndices[0].time) || '';
const regimeCode = escapeHtml(regime.market_regime_code || 'N/A');
const regimeState = escapeHtml(regime.market_state || 'N/A');
const regimeDesc = escapeHtml(regime.market_description || '');

const marketOverviewHtml = [
  `<b>1. MARKET OVERVIEW</b>`,
  ``,
  `<b>Market Indices:</b>`,
  indexBlocks,
  ``,
  `<b>Market Regime:</b>`,
  `• <b>State:</b> <code>${regimeCode}</code> — <b>${regimeState}</b>`,
  `• <b>Target Allocation:</b> ${allocText}`,
  `• <b>Description:</b> ${regimeDesc}`
].join('\n');

return [{
  json: {
    market_overview_html: marketOverviewHtml
  }
}];

// Retrieve watchlist rows from previous node
const rawInput = $input.first().json;
const rows = rawInput.data || [];

// Optional: map pivot_s1_plus_1 by stock_key if sourced from a separate array/node
// Example: const pivotMap = new Map((otherNodeData || []).map(x => [x.stock_key, x.pivot_s1_plus_1]));
const pivotMap = new Map();

// Optional buffer below S1 (set to 0 to use exact pivot_s1_plus_1)
const buyBufferPct = 0.0; // Example: 0.005 for 0.5% below S1

const escapeHtml = (str) => String(str ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const fmtPrice = (val) => {
  if (val === undefined || val === null || val === '' || isNaN(Number(val))) return 'N/A';
  return Number(val).toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
};

// Deduplicate by stock_key (keeps the latest record)
const uniqueMap = new Map();
for (const row of rows) {
  if (row.stock_key) {
    uniqueMap.set(row.stock_key, row);
  }
}

// Sort descending by expected return T+2
const candidates = Array.from(uniqueMap.values()).sort(
  (a, b) => (Number(b.expected_return_t2_n20) || 0) - (Number(a.expected_return_t2_n20) || 0)
);

if (candidates.length === 0) {
  return [{
    json: {
      watchlist_html: `<b>2. BUY WATCHLIST</b>\n<i>No candidate tickers matched the screening criteria.</i>`
    }
  }];
}

const reportDate = candidates[0].date_key || '';

// Enrich each candidate with pivot_s1_plus_1 and potential_buy_price
const enriched = candidates.map(item => {
  const rawS1 = item.pivot_s1_plus_1 ?? pivotMap.get(item.stock_key);
  const s1Num = (rawS1 !== undefined && rawS1 !== null && rawS1 !== '' && !isNaN(Number(rawS1)))
    ? Number(rawS1)
    : null;
  const potentialBuyPrice = s1Num !== null
    ? s1Num * (1 - buyBufferPct)
    : null;

  return {
    ...item,
    pivot_s1_plus_1: s1Num,
    potential_buy_price: potentialBuyPrice
  };
});

// Build fixed-width table
const header = 'Ticker | Buy Price | E[R] T+2 | RSI(7/14)';
const divider = '-'.repeat(header.length);

const tableLines = enriched.map(item => {
  const ticker = String(item.stock_key).padEnd(6, ' ');
  const buyStr = fmtPrice(item.potential_buy_price).padStart(9, ' ');

  const erVal = (Number(item.expected_return_t2_n20) || 0) * 100;
  const erStr = `${erVal >= 0 ? '+' : ''}${erVal.toFixed(2)}%`.padStart(8, ' ');

  const rsi7 = Math.round(Number(item.rsi_7) || 0);
  const rsi14 = Math.round(Number(item.rsi_14) || 0);
  const rsiStr = `${rsi7} / ${rsi14}`.padStart(9, ' ');

  return `${ticker} | ${buyStr} | ${erStr} | ${rsiStr}`;
});

// Build detailed execution & indicator lines
const detailLines = enriched.map(item => {
  const ticker = escapeHtml(item.stock_key);
  const buyFormatted = fmtPrice(item.potential_buy_price);
  const s1Formatted = fmtPrice(item.pivot_s1_plus_1);
  const s20 = Number(item.sma_20_slope_k1) || 0;
  const rsi7 = Number(item.rsi_7) || 0;

  const s20Str = `${s20 >= 0 ? '+' : ''}${s20.toFixed(2)}`;
  const rsiTag = rsi7 >= 70 ? ' (Overbought)' : (rsi7 <= 30 ? ' (Oversold)' : '');

  return `• <b>${ticker}:</b> Potential Buy <code>${buyFormatted}</code> (S1: <code>${s1Formatted}</code>) | SMA20 Slope <code>${s20Str}</code> | RSI7 <code>${rsi7.toFixed(1)}</code>${rsiTag}`;
});

const watchlistHtml = [
  `<b>2. BUY WATCHLIST</b>`,
  ``,
  `<pre><code class="language-text">${escapeHtml(header)}\n${divider}\n${escapeHtml(tableLines.join('\n'))}</code></pre>`,
  ``,
  `<b>Execution &amp; Momentum Details:</b>`,
  detailLines.join('\n')
].join('\n');

return [{
  json: {
    candidates: enriched,
    watchlist_html: watchlistHtml
  }
}];

// Retrieve items emitted by the Postgres node
const items = $input.all().map((item) => item.json);

// Escape HTML special characters for Telegram HTML parse mode
const escapeHtml = (str) =>
  String(str ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

// Parse numeric string safely and format with thousand separators
const parseNum = (val) => {
  const num = Number(val);
  return Number.isFinite(num) ? num : 0;
};

const fmtNum = (val, decimals = 0) =>
  parseNum(val).toLocaleString('en-US', {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  });

const generatedAt = $now.setZone('Asia/Ho_Chi_Minh').toFormat('dd/MM/yyyy HH:mm');

// Handle empty order set
const validItems = items.filter((row) => row && row.symbol);

if (validItems.length === 0) {
  const emptyDate = $now.setZone('Asia/Ho_Chi_Minh').toFormat('yyyy-MM-dd');
  const emptyMessage = [
    '<b>DAILY ORDER BOOK REPORT</b>',
    '<i>No orders recorded for this date.</i>',
  ].join('\n');

  return [{ json: { telegram_order_html: emptyMessage } }];
}

// Extract trade date from the first record
const reportDate = validItems[0].trade_date
  ? String(validItems[0].trade_date).slice(0, 10)
  : $now.setZone('Asia/Ho_Chi_Minh').toFormat('yyyy-MM-dd');

const buyOrders = [];
const sellOrders = [];
const accountSet = new Set();

let totalBuyAmount = 0;
let totalSellAmount = 0;

for (const row of validItems) {
  const tradeType = String(row.trade_type || '').toUpperCase().trim();
  const qty = parseNum(row.quantity);
  const price = parseNum(row.price);
  const amount = row.total_amount !== undefined && row.total_amount !== null
    ? parseNum(row.total_amount)
    : qty * price;

  if (row.account_id) {
    accountSet.add(String(row.account_id));
  }

  if (tradeType === 'BUY') {
    buyOrders.push({ ...row, _qty: qty, _price: price, _amount: amount });
    totalBuyAmount += amount;
  } else {
    sellOrders.push({ ...row, _qty: qty, _price: price, _amount: amount });
    totalSellAmount += amount;
  }
}

// Render fixed-width table in VND
const buildOrderTable = (orderList) => {
  const header = 'SYMBOL |    QTY |      PRICE | TOTAL (VND)';
  const divider = '-'.repeat(header.length);

  const lines = orderList.map((o) => {
    const symbol = String(o.symbol).padEnd(6, ' ');
    const qty = fmtNum(o._qty, 0).padStart(6, ' ');
    const price = fmtNum(o._price, 0).padStart(10, ' ');
    const total = fmtNum(o._amount, 0).padStart(11, ' ');
    return `${symbol} | ${qty} | ${price} | ${total}`;
  });

  return `<pre><code class="language-text">${escapeHtml(header)}\n${divider}\n${escapeHtml(lines.join('\n'))}</code></pre>`;
};

const detailBlocks = [];

if (buyOrders.length > 0) {
  detailBlocks.push(`🟢 <b>BUY orders (${buyOrders.length})</b>\n${buildOrderTable(buyOrders)}`);
}

if (sellOrders.length > 0) {
  detailBlocks.push(`🔴 <b>SELL orders (${sellOrders.length})</b>\n${buildOrderTable(sellOrders)}`);
}

const accountsList = Array.from(accountSet)
  .map((acc) => `<code>${escapeHtml(acc)}</code>`)
  .join(', ');

const finalMessage = [
  '<b>3. ORDER BOOK</b>',
  '',
  '<b>Summary</b>',
  `• <b>Total Orders:</b> <code>${validItems.length}</code> (<code>${buyOrders.length}</code> BUY • <code>${sellOrders.length}</code> SELL)`,
  `• <b>Buy Value:</b> <code>${fmtNum(totalBuyAmount, 0)}</code> VND`,
  `• <b>Sell Value:</b> <code>${fmtNum(totalSellAmount, 0)}</code> VND`,
  '',
  '<b>Details</b>',
  '',
  detailBlocks.join('\n\n'),
  '',
  `<i>Account(s): ${accountsList || 'N/A'}</i>`,
].join('\n');

return [{
  json: {
    order_html: finalMessage,
  },
}];

// Retrieve corporate actions rows from previous ClickHouse node output
const rawInput = $input.first().json;
const rows = Array.isArray(rawInput.data) ? rawInput.data : [];

// Escape HTML special characters required by Telegram HTML parse mode
const escapeHtml = (str) =>
  String(str ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

const generatedAt = $now.setZone('Asia/Ho_Chi_Minh').toFormat('dd/MM/yyyy HH:mm');

if (rows.length === 0) {
  const emptyHtml = [
    '📅 <b>CORPORATE ACTIONS CALENDAR</b>',
    `🕒 <i>Generated ${generatedAt}</i>`,
    '',
    '━━━━━━━━━━━━━━━━━━',
    '<i>No upcoming corporate action events found.</i>',
  ].join('\n');

  return [{ json: { corporate_actions_html: emptyHtml } }];
}

// Deduplicate by symbol + event_type + ex_rights_date, retaining the latest created_at
const dedupMap = new Map();

for (const row of rows) {
  if (!row || !row.symbol) continue;
  const symbol = String(row.symbol).trim();
  const eventType = String(row.event_type || '').trim();
  const exDate = String(row.ex_rights_date || '').trim();
  const key = `${symbol}__${eventType}__${exDate}`;

  const existing = dedupMap.get(key);
  const currentTs = Date.parse(String(row.created_at || '').replace(' ', 'T')) || 0;
  const existingTs = existing
    ? Date.parse(String(existing.created_at || '').replace(' ', 'T')) || 0
    : -1;

  if (!existing || currentTs >= existingTs) {
    dedupMap.set(key, {
      symbol,
      event_type: eventType || 'N/A',
      description: String(row.description || '').trim(),
      ex_rights_date: exDate || 'N/A',
      created_at: row.created_at || '',
    });
  }
}

const uniqueEvents = Array.from(dedupMap.values()).sort((a, b) => {
  if (a.ex_rights_date !== b.ex_rights_date) {
    return a.ex_rights_date.localeCompare(b.ex_rights_date);
  }
  return a.symbol.localeCompare(b.symbol);
});

// Count event types
let divCount = 0;
let issCount = 0;

for (const ev of uniqueEvents) {
  if (ev.event_type === 'DIV') divCount += 1;
  else if (ev.event_type === 'ISS') issCount += 1;
}

const firstDate = uniqueEvents[0]?.ex_rights_date || 'N/A';
const lastDate = uniqueEvents[uniqueEvents.length - 1]?.ex_rights_date || 'N/A';

// Group unique events by ex_rights_date
const groupedByDate = new Map();
for (const ev of uniqueEvents) {
  if (!groupedByDate.has(ev.ex_rights_date)) {
    groupedByDate.set(ev.ex_rights_date, []);
  }
  groupedByDate.get(ev.ex_rights_date).push(ev);
}

const dateSections = [];

for (const [dateStr, events] of groupedByDate.entries()) {
  const lines = events.map((ev) => {
    const prefixPattern = new RegExp(`^${ev.symbol}\\s*-\\s*`, 'i');
    const cleanDesc = ev.description.replace(prefixPattern, '');

    return `• <b>${escapeHtml(ev.symbol)}</b> [<code>${escapeHtml(ev.event_type)}</code>] - ${escapeHtml(cleanDesc)}`;
  });

  dateSections.push(
    [`📌 <i>Ex-Rights Date: <code>${escapeHtml(dateStr)}</code></i>`, ...lines].join('\n')
  );
}

const corporateActionsHtml = [
  '<b>4. CORPORATE ACTIONS CALENDAR</b>',
  '',
  '<b>Summary</b>',
  `• <b>Unique Events:</b> <code>${uniqueEvents.length}</code> (<code>${divCount}</code> DIV • <code>${issCount}</code> ISS)`,
  `• <b>Date Span:</b> <code>${escapeHtml(firstDate)}</code> → <code>${escapeHtml(lastDate)}</code>`,
  '',
  '<b>Upcoming ex-rights events</b>',
  '',
  dateSections.join('\n\n'),
].join('\n');

return [
  {
    json: {
      unique_events_count: uniqueEvents.length,
      corporate_actions_html: corporateActionsHtml,
    },
  },
];
